"""Netact ne integrator"""
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase


class NeIntegrator(NetactBase):
    """Netact ne integrator"""
    def __init__(self):
        super(NeIntegrator, self).__init__()

    def integrate_mrbts_with_netact(self, **kwargs):
        """
        Keyword integrates MRBTS with NetAct using Automatic Integration Framework.
        Parameters:
            release (string) SW release e.g. SBTS18 or FL19 (case insensitive).
            mr (string) Maintenance region of network element (created via Monitor),
                e.g. 'MRC_COMMON/MR_COMMON'.
            mrbts_address (string) Fully qualified domain name of MRBTS (or IP address) or
                BTS Mediator, e.g.: 'mrbts-123456' or 'mrbts-123456.btsmed-1'.
            dist_name (string) The distinguished name of the network element,
                e.g.: PLMN-PLMN/MRBTS-123456.
            presentation_name (string) (Optional) The network element name presented on the Monitor.
            http_port (string) HTTP port where NE3SWS agent is running.
            https_port (string) HTTPS port where NE3SWS agent is running.
            ip_version (string) IP protocol version network element uses:
                'IPv4' or 'IPv6' (case insensitive).
            security_mode (string) TLS (Transport Layer Security) supported:
                'TLS' or 'no TLS' (case insensitive).
            mrbts_em_address (string) Fully qualified domain name of MRBTS (or IP address),
                e.g.: 'mrbts-123456'. This parameter corresponds to the MRBTS EM address field
                from WEB UI in case of FL SW releases or to SBTS address field in case of SBTS
                SW releases. Please leave default value only if both mentioned fields are not
                available in WEB UI of NE Integration Wizard.
            certificate_type (string) Allowed values (case insensitive): Already installed or
                Install via CMP. If set to Install via CMP then cmp parameter must be configured.
            cmp (dict) If certificate_type is set to Install via CMP then CMPserverHost,
                CMPserverPort, CMPserverPath, CAName attributes are mandatory.
                e.g {
                    'CMPserverHost': '127.0.0.1',
                    'CMPserverPort': '1234',
                    'CMPserverPath': 'serverpath',
                    'CAName': 'name'
                    'referenceNo': '123'
                    'sharedKey': 'key'
                    'CAUpdateTime': '1'
                    'NEUpdateTime': '2'
                    }
            alias (string) Name of execution context.
        Returns:
        integration logs
        Return type:
        string
        """
        release = kwargs['release']
        maintenance_region = kwargs['mr']
        mrbts_address = kwargs['mrbts_address']
        dist_name = kwargs['dist_name']
        presentation_name = kwargs.pop('presentation_name', 'default')
        http_port = kwargs.pop('http_port', 'default')
        https_port = kwargs.pop('https_port', 'default')
        ip_version = kwargs.pop('ip_version', 'default')
        security_mode = kwargs.pop('security_mode', 'default')
        mrbts_em_address = kwargs.pop('mrbts_em_address', 'default')
        certificate_type = kwargs.pop('certificate_type', 'Already Installed')
        cmp = kwargs.pop('cmp', None)
        alias = kwargs.pop('alias', 'default')
        # return self.netact_factory.ne_integrator.integrate_mrbts_with_netact(
        #     release=release, mr=maintenance_region, mrbts_address=mrbts_address,
        #     dist_name=dist_name, presentation_name=presentation_name,
        #     http_port=http_port, https_port=https_port, ip_version=ip_version,
        #     security_mode=security_mode, mrbts_em_address=mrbts_em_address,
        #     alias=alias)
        return self.netact_factory.netact.integrate_mrbts_with_netact(
            release=release, mr=maintenance_region, mrbts_address=mrbts_address,
            dist_name=dist_name, presentation_name=presentation_name,
            http_port=http_port, https_port=https_port, ip_version=ip_version,
            security_mode=security_mode, mrbts_em_address=mrbts_em_address,
            certificate_type=certificate_type, cmp=cmp, alias=alias)

    def deintegrate_mrbts_from_netact(self, **kwargs):
        """
        Keyword de-integrates MRBTS with NetAct using Automatic Integration Framework CLI.

        *EMSSIM*
        Not applicable

        *NETACT*
        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | dist_name | Mandatory | The distinguished name of the network element,
            e.g.: PLMN-PLMN/MRBTS-123456. |  |
        | alias | 'default' | Name of execution context. |  |

        Returns: de-integration logs

        Return type: string
        """
        dist_name = kwargs['dist_name']
        alias = kwargs.pop('alias', 'default')
        return self.netact_factory.netact.deintegrate_mrbts_from_netact(dist_name, alias=alias)
